-- 1125: Blog post — "AZ-104 Azure Administrator in Singapore: Exam Domains, Funding and Practice Exams"
--
--       Lead-in post for WSQ - Microsoft Certified Azure Administrator Associate (AZ-104) (TGS-2023039182).
--       Backdated to 2025-09-23 (published, status 1). No LinkedIn / Facebook share is
--       performed: linkedin_urn carries the manual-skip sentinel and the post ships
--       already-published, so publishDue never picks it up.
--
-- Every figure below was read off the LIVE course page on 2026-08-26, not invented:
--   * Fee card: full $2,500.00, GST $225.00 (9%), baseline nett $1,475.00
--     (SG/PR 21+, 50%), MCES/SME nett $975.00 (SG 40+, 70%).
--   * Course information: 5 days / 40 hrs, Beginner, 2 hrs assessment.
--   * Funding validity 20 Oct 2023 - 19 Oct 2027; Absentee Payroll $4.50/hr.
--   * Skills Framework: Cloud Computing (ICT-DIT-4020-1.1).
--   * Exam weightings from the official study guide, skills measured as of 17 Apr 2026.
--   * Practice-exam URL verified HTTP 200: https://exams.tertiaryinfotech.com/practice-exams/microsoft/microsoft-az-104
--
-- Notes for future editors:
--  * apply.php splits statements on ";" at end-of-line — the content HTML below is ONE line.
--  * Idempotent: WHERE NOT EXISTS on url_key, INSERT IGNORE on tag links. Safe to re-run.
--  * SG-only guard via @mms_instance — the CTA course is SG WSQ, absent on MY/GH.
--  * hero_image_url is NOT set here (SQL cannot render one) — generate on prod post-deploy.

SET @is_sg := IF(@mms_instance = 'SG', 1, 0);

INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `linkedin_urn`, `created_at`, `updated_at`) SELECT 'AZ-104 Azure Administrator in Singapore: Exam Domains, Funding and Practice Exams', 'az-104-azure-administrator-singapore-guide', 'AZ-104 is the Microsoft credential for sysadmins and infrastructure engineers running production workloads on Azure. This guide walks the exam domains and their weightings, sets out exactly what you pay after WSQ funding &mdash; $1,475 nett, or $975 for Singapore Citizens aged 40 and above &mdash; and shows what the 5 days course covers.', '<div class="mmd-summary"><div class="mmd-summary-label">Summary</div><p><strong>AZ-104</strong> is the Microsoft credential for sysadmins and infrastructure engineers running production workloads on Azure. This guide covers what the exam measures, what the 5 days WSQ course covers, and what you pay after SkillsFuture funding &mdash; <strong>$1,475</strong> for Singapore Citizens and PRs aged 21 and above, or <strong>$975</strong> for Singapore Citizens aged 40 and above.</p></div><h2>Why AZ-104 is worth sitting</h2><p>AZ-104 is the workhorse Azure certification &mdash; the one hiring managers actually look for when filling cloud operations roles. It covers the daily reality of running Azure: identities and governance, storage, compute, networking and monitoring, with enough depth that passing it means you can genuinely operate a subscription.</p><ul><li><strong>It is the most widely recognised Azure operations credential</strong> and appears constantly in Singapore infrastructure job listings.</li><li><strong>It is a prerequisite for AZ-400</strong>, so it is also the gateway to the DevOps Engineer Expert certification.</li><li><strong>Identities, governance and compute carry the most weight</strong> at 20&ndash;25% each &mdash; this is an exam about running things safely, not just deploying them.</li><li><strong>At 5 days it is the most substantial course in this catalogue</strong>, reflecting the breadth of the exam.</li></ul><p>The course is mapped to the Skills Framework under <strong>Cloud Computing</strong> (TSC code ICT-DIT-4020-1.1), and leads to roles such as Azure Administrator, Systems Administrator, Network Administrator, Cloud Solutions Architect. <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-azure-administrator-associate-az-104.html">Check the funding you qualify for</a>.</p><h2>The AZ-104 exam at a glance</h2><table><tbody><tr><td>Exam</td><td>AZ-104: Microsoft Azure Administrator</td></tr><tr><td>Length</td><td>100 minutes</td></tr><tr><td>Passing score</td><td>700 out of 1000 (scaled &mdash; not 70%)</td></tr><tr><td>Certification</td><td>Azure Administrator Associate</td></tr><tr><td>Renewal</td><td>Free online renewal every 12 months</td></tr></tbody></table><h2>AZ-104 exam domains and weightings</h2><p>These are the skills measured on the official study guide. The weightings tell you where to spend your revision time.</p><table><thead><tr><th>Skills measured</th><th>Weighting</th></tr></thead><tbody><tr><td>Manage Azure identities and governance</td><td>20&ndash;25%</td></tr><tr><td>Implement and manage storage</td><td>15&ndash;20%</td></tr><tr><td>Deploy and manage Azure compute resources</td><td>20&ndash;25%</td></tr><tr><td>Implement and manage virtual networking</td><td>15&ndash;20%</td></tr><tr><td>Monitor and maintain Azure resources</td><td>10&ndash;15%</td></tr></tbody></table><p><em>Source: official Microsoft study guide, skills measured as of 17 Apr 2026.</em></p><h2>What the WSQ course covers</h2><p>The 5 days (40 hrs) <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-azure-administrator-associate-az-104.html"><strong>WSQ - Microsoft Certified Azure Administrator Associate (AZ-104)</strong></a> course is pitched at <strong>Beginner</strong> level and is delivered in our Woodlands classroom with hands-on labs, followed by a 2 hrs assessment. The outline tracks the official objectives:</p><ol><li>Configure Azure resources with tools</li><li>Use Azure Resource Manager</li><li>Configure resources with Azure Resource Manager templates</li><li>Automate Azure tasks using scripts with PowerShell</li><li>Control Azure services with the CLI</li><li>Deploy Azure infrastructure by using JSON ARM templates</li><li>Configure Azure Active Directory</li><li>Configure user and group accounts</li><li>Configure subscriptions</li><li>Configure Azure Policy</li><li>Configure role-based access control</li><li>Create Azure users and groups in Azure Active Directory</li><li>Secure your Azure resources with Azure role-based access control (Azure RBAC)</li><li>Allow users to reset their password with Azure Active Directory self-service password reset</li></ol><p>The full outline runs to 51 topics &mdash; see the <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-azure-administrator-associate-az-104.html">course page</a> for the complete list.</p><h2>Practise before you book the exam</h2><p>Course participants get free, unlimited access to our <a href="https://exams.tertiaryinfotech.com/practice-exams/microsoft/microsoft-az-104">AZ-104 practice exams</a> on the Tertiary Infotech Practice Exam Portal, in both Practice Mode (with instant explanations) and timed Exam Mode. The portal offers non-participants 10 free questions per exam.</p><h2>What you actually pay: funding for AZ-104 training</h2><p>The full fee is $2,500 before GST. As an SWDA-funded WSQ course, the subsidy depends on your citizenship, age and who is sponsoring you:</p><table><thead><tr><th>Who you are</th><th>Subsidy</th><th>You pay (incl. GST)</th></tr></thead><tbody><tr><td>Non-funded / international participants</td><td>&ndash;</td><td>$2,725</td></tr><tr><td>Singapore Citizen or PR, aged 21 and above</td><td>50%</td><td><strong>$1,475</strong></td></tr><tr><td>Singapore Citizen aged 40 and above (MCES), or SME-sponsored</td><td>70%</td><td><strong>$975</strong></td></tr></tbody></table><p><em>GST of $225 is charged at 9% on the full course fee of $2,500, as required for SWDA-funded courses &mdash; the subsidy applies to the course fee, not the tax.</em></p><p>Funding for this course is valid from <strong>20 Oct 2023</strong> to <strong>19 Oct 2027</strong>. You must register and complete the course within that window to qualify.</p><div class="mmd-faq"><details class="mmd-faq-item"><summary class="mmd-faq-q">1. SkillsFuture Credit (SFC)</summary><div class="mmd-faq-a"><p>Singaporeans aged 25 and above have an opening SkillsFuture Credit of $500 plus any top-ups, and those aged 40 and above received a $4,000 Mid-Career top-up. Credit can offset the fee payable after subsidy, though the Mid-Career top-up cannot be used on this course. <a href="https://www.tertiarycourses.com.sg/how-to-claim-skillsfuture-credit.html">How to claim SkillsFuture Credit</a>.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">2. SkillsFuture Enterprise Credit (SFEC)</summary><div class="mmd-faq-a"><p>Eligible employers can draw on SFEC to cover out-of-pocket costs when sponsoring staff. See our <a href="https://www.tertiarycourses.com.sg/sfec.html">SFEC guide</a> for who qualifies and how to claim.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">3. PSEA</summary><div class="mmd-faq-a"><p>Singapore Citizens can use Post-Secondary Education Account funds to offset the fee payable after subsidy. This course carries the PSEA tag, so it is eligible.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">4. UTAP</summary><div class="mmd-faq-a"><p>NTUC members can claim 50% of the unfunded fee under UTAP, capped at $250 a year, or $500 a year for members aged 40 and above. See the <a href="https://www.tertiarycourses.com.sg/utap.html">UTAP guide</a>.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">5. Absentee Payroll</summary><div class="mmd-faq-a"><p>Employers sponsoring staff can claim Absentee Payroll at $4.50 an hour, capped at $100,000 per enterprise per year, for the hours staff spend in training.</p></div></details></div><p><a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-azure-administrator-associate-az-104.html"><strong>See the live fee breakdown for your profile &rarr;</strong></a></p><h2>Your route to certification</h2><ol><li><strong>Register for the 5 days WSQ course.</strong> Pick an intake on the <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-azure-administrator-associate-az-104.html">course page</a> and apply your funding at checkout.</li><li><strong>Attend and complete the assessment.</strong> You need at least 75% attendance and a pass in the 2 hrs assessment to receive your WSQ Statement of Attainment.</li><li><strong>Rehearse on the practice exams</strong> until you are consistently clearing the pass mark under timed conditions.</li><li><strong>Book and sit AZ-104</strong> through Pearson VUE. The certification exam is booked and paid for separately from the course.</li></ol><h2>Where to go after AZ-104</h2><p>From AZ-104 the two common paths are <a href="https://www.tertiarycourses.com.sg/wsq-designing-and-implementing-microsoft-devops-solutions-az-400.html">AZ-400 for DevOps</a> or AZ-305 for solutions architecture. For the security side, <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-identity-and-access-administrator-sc-300.html">SC-300</a> goes deeper on identity. Browse the full <a href="https://www.tertiarycourses.com.sg/microsoft-certifications-exams.html">Microsoft certification course catalogue</a> to plan the next rung.</p><h2>Frequently asked questions</h2><div class="mmd-faq"><details class="mmd-faq-item"><summary class="mmd-faq-q">Do I need AZ-900 before AZ-104?</summary><div class="mmd-faq-a"><p>Not formally &mdash; AZ-900 is not a prerequisite. But AZ-104 assumes you already understand core Azure concepts, so candidates without cloud experience usually find AZ-900 a worthwhile starting point.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">How hard is AZ-104?</summary><div class="mmd-faq-a"><p>It is a genuine associate-level exam covering five broad domains. The passing score is 700 out of 1000 on a scaled basis, which is not the same as 70% of questions correct.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Is the exam fee included?</summary><div class="mmd-faq-a"><p>No. The course fee covers training and the WSQ assessment. The AZ-104 exam is booked separately through Pearson VUE.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Does the certification expire?</summary><div class="mmd-faq-a"><p>Yes, annually &mdash; but renewal is free, unproctored and done online through Microsoft Learn within a six-month window.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">What does the course cost after funding?</summary><div class="mmd-faq-a"><p>The full fee is $2,500 before GST. Singapore Citizens and PRs aged 21 and above pay $1,475, and Citizens aged 40 and above pay $975, both inclusive of GST.</p></div></details></div><h2>Register for Azure Administrator training</h2><p>Seats are limited and classes fill ahead of each intake. View upcoming dates and reserve your place on the <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-azure-administrator-associate-az-104.html"><strong>WSQ - Microsoft Certified Azure Administrator Associate (AZ-104)</strong></a> course page, or call us on +65 6100 0613 if you would like your funding worked out first.</p>', 'Tertiary Infotech Academy', 1, '2025-09-23', 'TGS-2023039182', 'TGS-2023039182', 'AZ-104 Course Singapore | Azure Administrator | WSQ Funding', 'Train for AZ-104 Azure Administrator in Singapore. 5 days WSQ course from $975 nett after funding, full exam domain breakdown, and free practice exams for participants.', 'az-104 course singapore, azure administrator certification, az-104 exam, wsq microsoft course, skillsfuture microsoft certification, microsoft certification singapore, az-104 funding, az-104 training singapore', 'manual-skip-no-share', '2025-09-23 09:00:00', '2025-09-23 09:00:00' FROM DUAL WHERE @is_sg > 0 AND NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'az-104-azure-administrator-singapore-guide');

