INSERT INTO `tag` (`name`, `status`) SELECT 'Azure', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Azure') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'AZ-104', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'AZ-104') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'Cloud Administration', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Cloud Administration') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'WSQ', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'WSQ') x);

SET @post_id := (SELECT `post_id` FROM `mmd_blog_post` WHERE `url_key` = 'az-104-azure-administrator-singapore-guide');

